src/crypto/MindPatternCrypto.ts.source:
/**
 * The device-side crypto orchestrator: key derivation, entry envelopes,
 * and decryption of insight/question payloads. Mirrors backend/tests/helpers.py
 * (the client emulator) — if these ever disagree, shared/vectors.json fails.
 */
import { buildAad, decrypt, encrypt } from "./envelope";
import { deriveAuthKey, deriveDataKey, deriveMasterKey, deriveMasterKeyAsync, zeroize } from "./kdf";

export interface Keys {
  masterKey: Buffer;
  authKey: Buffer; // only this ever crosses the network (as the login verifier)
  dataKey: Buffer; // encrypts everything
}

export interface EntryPayload {
  v: 1;
  text: string;
  sentiment: number | null; // computed on-device before encryption
  created_at: string; // ISO date
}

export function deriveKeys(password: string, salt: Buffer): Keys {
  const masterKey = deriveMasterKey(password, salt);
  return { masterKey, authKey: deriveAuthKey(masterKey), dataKey: deriveDataKey(masterKey) };
}

/** deriveKeys without the JS-thread freeze (see deriveMasterKeyAsync) —
 *  the login/unlock screens' preferred path. */
export async function deriveKeysAsync(password: string, salt: Buffer): Promise<Keys> {
  const masterKey = await deriveMasterKeyAsync(password, salt);
  return { masterKey, authKey: deriveAuthKey(masterKey), dataKey: deriveDataKey(masterKey) };
}

export function encryptEntry(
  keys: Pick<Keys, "dataKey">,
  userId: string,
  clientEntryId: string,
  text: string,
  createdAt: string,
  sentiment: number | null,
): { blobB64: string } {
  const payload: EntryPayload = { v: 1, text, sentiment, created_at: createdAt };
  // Stryker disable StringLiteral
const plaintext = Buffer.from(JSON.stringify(payload), "utf8");
  // Stryker restore StringLiteral
  const aad = buildAad("entry", userId, clientEntryId);
  const blob = encrypt(keys.dataKey, plaintext, aad);
  return { blobB64: blob.toString("base64") };
}

export function decryptEntry(
  keys: Pick<Keys, "dataKey">,
  userId: string,
  clientEntryId: string,
  blobB64: string,
): EntryPayload {
  const plaintext = decrypt(keys.dataKey, Buffer.from(blobB64, "base64"), buildAad("entry", userId, clientEntryId));
  return JSON.parse(plaintext.toString("utf8")) as EntryPayload;
}

/** The only insights payload schema this client understands (the backend
 *  emits "v": 2). An unknown version must fail LOUDLY here — silently
 *  parsing a future schema as if it were v2 is how a schema roll corrupts
 *  the UI with misread fields. Mirrors the InsightsScreen phase guard. */
export const INSIGHTS_PAYLOAD_VERSION = 2;

export interface InsightsPayload {
  v: number;
  stats?: { patterns?: unknown };
}

export function decryptInsights(keys: Pick<Keys, "dataKey">, userId: string, blobB64: string): InsightsPayload {
  const plaintext = decrypt(keys.dataKey, Buffer.from(blobB64, "base64"), buildAad("insights", userId, "patterns"));
  const payload = JSON.parse(plaintext.toString("utf8")) as { v?: unknown };
  if (payload.v !== INSIGHTS_PAYLOAD_VERSION) {
    throw new Error(`unsupported insights payload version: ${String(payload.v)}`);
  }
  return payload as unknown as InsightsPayload;
}

export function decryptQuestion(keys: Pick<Keys, "dataKey">, userId: string, forDate: string, blobB64: string) {
  const plaintext = decrypt(keys.dataKey, Buffer.from(blobB64, "base64"), buildAad("question", userId, forDate));
  return JSON.parse(plaintext.toString("utf8")) as { for_date: string; question: string };
}

export { zeroize };

src/crypto/aad.ts.source:
/**
 * Canonical AAD construction — pure, dependency-free, and byte-identical to
 * backend/app/security/crypto.py's build_aad.
 *
 * The backend canonicalizes with Python json.dumps(..., ensure_ascii=True):
 * a compact JSON array in which every UTF-16 code unit >= 0x7F is escaped
 * as \uXXXX (astral characters therefore appear as surrogate-pair escapes).
 * Python's ensure_ascii range is "outside 0x20..0x7E", so DEL (0x7F) IS
 * escaped on both platforms — verified against CPython and vectors.json.
 * JS JSON.stringify keeps such characters raw — so we post-process. Control
 * characters (\b \f \n \r \t) and the quotes/backslash use identical
 * short escapes in both languages and need no handling here.
 *
 * shared/vectors.json pins this byte-for-byte with non-ASCII and astral
 * cases; if you change anything in this file, regenerate vectors and run
 * `npm test` on BOTH platforms before shipping.
 */

function escapeAsciiChar(code: number): string {
  return "\\u" + code.toString(16).padStart(4, "0");
}

function toEnsureAscii(text: string): string {
  let out = "";
  for (let i = 0; i < text.length; i++) {
    const code = text.charCodeAt(i);
    out += code >= 0x7f ? escapeAsciiChar(code) : text[i];
  }
  return out;
}

export function buildAad(...parts: string[]): Buffer {
  const arrayJson = JSON.stringify(parts);
  // The JSON structure itself is pure ASCII after this pass; only the
  // string contents could contain non-ASCII, and JSON.stringify escapes
  // structural characters itself, so escaping the WHOLE serialization is
  // safe: nothing outside string literals can be >= 0x7F.
  // Stryker disable StringLiteral
return Buffer.from(toEnsureAscii(arrayJson), "utf8");
  // Stryker restore StringLiteral
}

src/crypto/kdf.ts.source:
/**
 * Client-side key schedule — must match backend/app/security/kdf.py exactly.
 *
 *   master_key = PBKDF2-HMAC-SHA256(password, salt, 600_000)
 *   auth_key   = HKDF-SHA256(master_key, info="mindpattern/auth/v1")  -> sent to server
 *   data_key   = HKDF-SHA256(master_key, info="mindpattern/data/v1")  -> never leaves
 *                                                            the device, except into a
 *                                                            TLS-delivered, single-use
 *                                                            processing session.
 *
 * Byte-for-byte compatibility is pinned by shared/vectors.json; run
 * `npm test` (the real modules against the vectors) — it replaces the old
 * webcrypto-only reference check.
 */
import { engine } from "./engine";

export const KDF_ITERATIONS = 600_000;
const MIN_SALT_SIZE = 8;

// HKDF info strings are rebuilt at call time, not captured at module scope:
// every derivation then exercises (and mutation-tests) the exact label
// bytes, and no warm test worker can cache a stale value.
function authInfo(): Buffer {
  // "utf8" is Buffer's default; an empty encoding string decodes identically.
// Stryker disable StringLiteral
return Buffer.from("mindpattern/auth/v1", "utf8");
// Stryker restore StringLiteral
}

function dataInfo(): Buffer {
  // Stryker disable StringLiteral
return Buffer.from("mindpattern/data/v1", "utf8");
  // Stryker restore StringLiteral
}

export function deriveMasterKey(password: string, salt: Buffer, iterations = KDF_ITERATIONS): Buffer {
  if (salt.length < MIN_SALT_SIZE) {
    throw new Error(`salt must be at least ${MIN_SALT_SIZE} bytes`);
  }
  if (iterations < 1) {
    throw new Error("iterations must be positive");
  }
  return engine.pbkdf2Sync(password, salt, iterations, 32, "sha256");
}

/**
 * The async derivation — PREFER this in UI paths. The sync form freezes
 * the JS thread for ~100-400ms at 600k iterations; the engine's async
 * pbkdf2 (quick-crypto's JSI worker on device, node:crypto's thread pool
 * in tests) keeps the UI responsive. Same bytes, same vectors.
 */
export async function deriveMasterKeyAsync(
  password: string,
  salt: Buffer,
  iterations = KDF_ITERATIONS,
): Promise<Buffer> {
  if (salt.length < MIN_SALT_SIZE) {
    throw new Error(`salt must be at least ${MIN_SALT_SIZE} bytes`);
  }
  if (iterations < 1) {
    throw new Error("iterations must be positive");
  }
  return new Promise((resolve, reject) => {
    engine.pbkdf2(password, salt, iterations, 32, "sha256", (err, derivedKey) => {
      if (err) {
        reject(err);
        return;
      }
      if (!derivedKey) {
        reject(new Error("pbkdf2 produced no key"));
        return;
      }
      resolve(Buffer.from(derivedKey));
    });
  });
}

export function deriveAuthKey(masterKey: Buffer): Buffer {
  // Empty salt -> RFC 5869 default of HashLen zeros, matching the backend.
  return hkdfSha256(masterKey, authInfo());
}

export function deriveDataKey(masterKey: Buffer): Buffer {
  return hkdfSha256(masterKey, dataInfo());
}

/**
 * hkdfSync returns an ArrayBuffer (Node API parity in quick-crypto), not a
 * Buffer — wrap it so Buffer methods (toString("base64"), fill, subarray)
 * actually exist on the result.
 */
function hkdfSha256(ikm: Buffer, info: Buffer): Buffer {
  const derived = engine.hkdfSync("sha256", ikm, Buffer.alloc(32), info, 32);
  return Buffer.from(derived as ArrayBuffer);
}

/** Overwrite key material buffers as soon as they are no longer needed. */
export function zeroize(...buffers: (Buffer | undefined | null)[]): void {
  for (const buf of buffers) {
    if (buf) buf.fill(0);
  }
}

src/genericQuestions.ts.source:
/**
 * The generic reflective question pool — EMBEDDED COPY of
 * shared/generic_questions.json (the cross-platform source of truth).
 *
 * Why embed instead of import: Metro cannot resolve modules outside the
 * project root, so the shared JSON cannot be imported at runtime (the same
 * reason shared/vectors.json is verified by a node tool). Sync is enforced
 * by tests/genericQuestions.test.ts, which reads the shared file from disk
 * and pins array parity plus the content invariants (every entry is a
 * question, none contains advice language).
 *
 * Scope: this pool serves PRE-THRESHOLD users only (a day-1 question while
 * the account is below the pattern threshold; the server-side engine takes
 * over after it). The rotation below is device-local and deterministic —
 * the same question all day, a different one tomorrow — but it is NOT
 * stable across platforms and does not need to be: the backend derives its
 * own daily question, and nothing compares the two.
 */
import { localDateISO } from "./moodLog";

export const GENERIC_QUESTIONS: readonly string[] = [
  "What took up most space in your mind today?",
  "What felt different today compared to yesterday?",
  "When did you feel most like yourself today?",
  "What's one small thing that went right today?",
  "What thought repeated itself today?",
  "If today had a title, what would it be?",
  "What are you carrying into tomorrow?",
  "What did you notice today that you usually overlook?",
];

/** djb2 over the date string: a pure function of the local calendar day,
 *  so the pick is stable within the day and rotates as the date changes.
 *  (Day-to-day rotation is not a uniform shuffle — consecutive dates land
 *  on adjacent pool slots — which is exactly the desired behavior.) */
function seedFromDate(date: string): number {
  let hash = 5381;
  // Stryker disable next-line EqualityOperator: the extra iteration multiplies the final seed by 33 (charCodeAt past the end is NaN, an XOR no-op) and 33 ≡ 1 (mod 8) — with the 8-item pool, seed % 8 picks the same index for every date
  for (let i = 0; i < date.length; i++) {
    hash = ((hash * 33) ^ date.charCodeAt(i)) >>> 0;
  }
  return hash;
}

/** The day's question for the given LOCAL calendar date (YYYY-MM-DD);
 *  defaults to today. */
export function genericQuestionForDate(date: string = localDateISO()): string {
  return GENERIC_QUESTIONS[seedFromDate(date) % GENERIC_QUESTIONS.length]!;
}

src/mood.ts.source:
/**
 * The mood vocabulary: the explicit check-in scale plus the quick
 * text-derived estimate. Shared by the Entry screen (the one-tap mood row
 * and the device-local mood log write) and the History screen (per-entry
 * mood badge).
 *
 * Values live in [-1, 1] — the range the mood log and the entry payload's
 * sentiment field already use. The labels deliberately avoid clinical and
 * judgmental language: Heavy and Light are states of the day, not verdicts
 * about the person.
 */
export interface MoodOption {
  value: number;
  label: string;
}

/** The five check-in picks, Heavy → Light. An explicit tap always wins over
 *  the text estimate; never tapping is fine and never blocks saving. */
export const MOOD_OPTIONS: readonly MoodOption[] = [
  { value: -1, label: "Heavy" },
  { value: -0.5, label: "Low" },
  { value: 0, label: "Okay" },
  { value: 0.5, label: "Good" },
  { value: 1, label: "Light" },
];

/** The closest scale label for any value in [-1, 1] — badges render the
 *  stored quick score, which is rarely one of the five exact picks. */
export function moodLabel(value: number): string {
  let best = MOOD_OPTIONS[0]!;
  for (const option of MOOD_OPTIONS) {
    if (Math.abs(option.value - value) < Math.abs(best.value - value)) best = option;
  }
  return best.label;
}

/** Quick client-side mood estimate: drives the local (device-only) trend
 *  view before patterns unlock. Never sent as plaintext metadata and, in
 *  the entry payload, only a deliberate check-in pick rides along — the
 *  server's graded engine re-scores the text at analysis time. */
export function localSentiment(text: string): number {
  const positive = (text.toLowerCase().match(/\b(good|great|happy|calm|grateful|relaxed|excited|proud|hopeful)\b/g) ?? []).length;
  const negative = (text.toLowerCase().match(/\b(bad|sad|anxious|anxiety|stressed|angry|worried|tired|lonely|overwhelmed)\b/g) ?? []).length;
  // When positive == negative the ratio below already evaluates to 0, so
  // `-` and `+` agree on every reachable input.
  // Stryker disable ArithmeticOperator
  if (positive + negative === 0) return 0;
  // Stryker restore ArithmeticOperator
  return Number(((positive - negative) / (positive + negative)).toFixed(2));
}

src/moodLog.ts.source:
/**
 * Device-local mood log for the baseline phase (pre-threshold feedback).
 *
 * One number per day, derived on-device from the day's entry — never
 * synced, never seen by the server. It powers the streak + mood-trend view
 * while the account is below the pattern threshold; after the threshold
 * the mini-brain's analysis (re-derived from the encrypted corpus)
 * replaces it.
 *
 * Privacy: the log is ENCRYPTED under the account's data key (AES-256-GCM,
 * AAD-bound to the account id) — the same key that encrypts entries. A
 * device-file-system reader gets ciphertext, not a mood trend. Values from
 * the pre-encryption format (raw JSON arrays) migrate transparently on
 * the next write. A corrupt/tampered blob degrades to empty: this log is
 * disposable metadata and must never crash or lock the app.
 *
 * Key custody: the public functions take the vault's SHARED dataKey buffer.
 * recordMood is commonly fire-and-forget, and vault.lock() (e.g. a
 * background transition) zeroizes that buffer mid-await — encrypting the
 * pending write under an all-zero key would produce a blob no future read
 * can open (the log would silently reset). Every public call therefore
 * SNAPSHOTS the key bytes into a private copy at call time, works from the
 * copy, and zeroizes the copy in finally.
 */
import AsyncStorage from "@react-native-async-storage/async-storage";
import { buildAad, decrypt, encrypt } from "./crypto/envelope";
import { zeroize } from "./crypto/kdf";

export interface MoodDay {
  date: string; // YYYY-MM-DD
  value: number; // [-1, 1]
}

const key = (userId: string): string => `mindpattern.moodlog.${userId}`;
const MAX_DAYS = 400;

/** Serializes every read-modify-write cycle: two rapid recordMood calls
 *  (or a record racing the legacy re-encryption write) used to lose one
 *  day's value to a last-write-wins race on a stale snapshot. */
let logMutex: Promise<unknown> = Promise.resolve();
function serialized<T>(operation: () => Promise<T>): Promise<T> {
  const run = logMutex.then(operation, operation);
  logMutex = run.catch(() => {});
  return run;
}

function yesterday(iso: string): string {
  const d = new Date(`${iso}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() - 1);
  return d.toISOString().slice(0, 10);
}

function todayIso(): string {
  return localDateISO();
}

/**
 * LOCAL calendar date (yyyy-mm-dd) in device time. `toISOString().slice(0,10)`
 * is the UTC day — wrong for everyone outside UTC in the evening — and it
 * feeds entry ids/dates and this log, so it must match the user's wall
 * calendar. Shared by the mood log and the entry screen.
 */
export function localDateISO(d: Date = new Date()): string {
  const year = String(d.getFullYear()).padStart(4, "0");
  const month = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function sanitize(raw: unknown): MoodDay[] {
  // Stryker disable next-line ConditionalExpression: with the guard skipped, for..of over a non-iterable throws inside read()'s try/catch and degrades to the same empty days
  if (!Array.isArray(raw)) return [];
  const days: MoodDay[] = [];
  for (const item of raw) {
    // Stryker disable next-line ConditionalExpression: destructuring any primitive yields undefined date/value members, so the checks below skip it identically
    if (typeof item !== "object" || item === null) continue;
    const { date, value } = item as Record<string, unknown>;
    // Stryker disable next-line ConditionalExpression: RegExp.test coerces its argument to a string, and no non-string JSON value stringifies to ^\d{4}-\d{2}-\d{2}$
    if (typeof date !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(date)) continue;
    // Stryker disable next-line LogicalOperator,ConditionalExpression: JSON.parse can never yield NaN/Infinity (the only inputs where these forms differ), and Number.isFinite returns false for every non-number without coercion
    if (typeof value !== "number" || !Number.isFinite(value)) continue;
    days.push({ date, value: Math.max(-1, Math.min(1, value)) });
  }
  days.sort((a, b) => a.date.localeCompare(b.date));
  return days;
}

/**
 * Read the log. The returned flag says whether the stored bytes were the
 * legacy plaintext format (so the caller re-writes them encrypted).
 */
async function read(dataKey: Buffer, userId: string): Promise<{ days: MoodDay[]; legacy: boolean }> {
  const raw = await AsyncStorage.getItem(key(userId));
  // Stryker disable next-line BooleanLiteral: the legacy flag is dead output — no caller reads it (all destructures take only days)
  if (!raw) return { days: [], legacy: false };
  if (raw.startsWith("[")) {
    // Pre-encryption format. Read-through migration: a user who only ever
    // READS (the Insights baseline view) must not keep a plaintext mood log
    // on disk forever — re-write the parsed days encrypted right away.
    try {
      const days = sanitize(JSON.parse(raw));
      await write(dataKey, userId, days);
      // Stryker disable next-line BooleanLiteral: the legacy flag is dead output — no caller reads it
      return { days, legacy: true };
    // Stryker disable next-line BlockStatement: with the catch emptied, a corrupt legacy blob falls through to the decrypt path, which also fails and returns the same empty days
    } catch {
      // Stryker disable next-line BooleanLiteral: the legacy flag is dead output — no caller reads it
      return { days: [], legacy: true };
    }
  }
  try {
    const plain = decrypt(
      dataKey,
      Buffer.from(raw, "base64"),
      buildAad("moodlog", userId),
    );
    // Stryker disable next-line BooleanLiteral: the legacy flag is dead output — no caller reads it
    return { days: sanitize(JSON.parse(plain.toString("utf8"))), legacy: false };
  } catch {
    // Wrong key (account switch), corruption, or tampering: disposable.
    // Stryker disable next-line BooleanLiteral: the legacy flag is dead output — no caller reads it
    return { days: [], legacy: false };
  }
}

async function write(dataKey: Buffer, userId: string, days: MoodDay[]): Promise<void> {
  const blob = encrypt(
    dataKey,
    // Stryker disable next-line StringLiteral: Buffer.from(str, "") is Node's UTF-8 default — the mutated encoding produces identical bytes (verified: no throw, same buffer)
    Buffer.from(JSON.stringify(days.slice(-MAX_DAYS)), "utf8"),
    buildAad("moodlog", userId),
  );
  await AsyncStorage.setItem(key(userId), blob.toString("base64"));
}

/** Upsert one day's mood (latest value wins for the same date). */
export async function recordMood(dataKey: Buffer, userId: string, date: string, value: number): Promise<void> {
  // Snapshot the key NOW, at call time — NOT inside the serialized block,
  // which may run much later (or after a lock zeroized the shared buffer).
  const keyCopy = Buffer.from(dataKey);
  try {
    await serialized(async () => {
      const { days } = await read(keyCopy, userId);
      const clean = Math.max(-1, Math.min(1, value));
      const existing = days.findIndex((d) => d.date === date);
      if (existing >= 0) days[existing] = { date, value: clean };
      else days.push({ date, value: clean });
      await write(keyCopy, userId, days);
    });
  // Stryker disable next-line BlockStatement: the finally block only zeroizes the private key copy (memory hygiene, unobservable after return)
  } finally {
    // Stryker disable next-line CallExpression: zeroize only scribbles the private key copy — unobservable from any caller
    zeroize(keyCopy);
  }
}

/** The most recent *days* mood entries, oldest first. */
export async function recentMoods(dataKey: Buffer, userId: string, days = 30): Promise<MoodDay[]> {
  const keyCopy = Buffer.from(dataKey);
  try {
    const readResult = await read(keyCopy, userId);
    return readResult.days.slice(-days);
  // Stryker disable next-line BlockStatement: the finally block only zeroizes the private key copy (memory hygiene, unobservable after return)
  } finally {
    // Stryker disable next-line CallExpression: zeroize only scribbles the private key copy — unobservable from any caller
    zeroize(keyCopy);
  }
}

/** Consecutive writing days ending today (yesterday counts, with grace). */
export async function localStreak(dataKey: Buffer, userId: string, today = todayIso()): Promise<number> {
  const keyCopy = Buffer.from(dataKey);
  try {
    const { days } = await read(keyCopy, userId);
    // Stryker disable next-line ConditionalExpression: with the guard skipped, an empty days array leaves cursor null and the !cursor guard below returns the same 0
    if (days.length === 0) return 0;
    const set = new Set(days.map((d) => d.date));
    let cursor = set.has(today) ? today : set.has(yesterday(today)) ? yesterday(today) : null;
    // Stryker disable next-line ConditionalExpression: with the guard skipped, a null cursor falls into the while loop whose set.has(null) never matches — streak stays 0, the identical result
    if (!cursor) return 0;
    let streak = 0;
    while (set.has(cursor)) {
      streak += 1;
      cursor = yesterday(cursor);
    }
    return streak;
  // Stryker disable next-line BlockStatement: the finally block only zeroizes the private key copy (memory hygiene, unobservable after return)
  } finally {
    // Stryker disable next-line CallExpression: zeroize only scribbles the private key copy — unobservable from any caller
    zeroize(keyCopy);
  }
}

/** Test seam: wipe the log (sign-out hygiene for tests and account switch). */
export async function clearMoodLog(userId: string): Promise<void> {
  await AsyncStorage.removeItem(key(userId));
}

