src/theme.ts.source:
/**
 * The MindPattern design system: one palette (dark is the default, light
 * follows the OS), plus the spacing / typography / radius scales every
 * screen is built from. No screen may hardcode a hex literal — if a color
 * is needed, it belongs here with its contrast checked.
 *
 * Contrast commitments (WCAG AA, 4.5:1 for normal text; computed with the
 * sRGB relative-luminance formula and pinned by tests/theme.test.ts):
 *
 *  dark.muted   #8a91a3 — 6.0:1 on bg #0f1115, 5.3:1 on card #1a1e26
 *               (replaces #5c6370, which measured 3.13:1 — the failing
 *               gray that carried the crisis-screen fine print)
 *  dark.onPrimary on primary #3b5bdb — 5.7:1 (replaces #4f7cff, 3.71:1)
 *  dark.accent  #7f9bff — 7.2:1 on bg, 5.5:1 on helpBg #242a38
 *  dark.body    #b6bdc9 — 10.0:1 on bg, 8.8:1 on card
 *  dark.error   #ff6b6b — 6.8:1 on bg
 *  light.muted  #5a6272 — 6.1:1 on card, 5.7:1 on bg #f5f6fa
 *  light.onPrimary on primary #2f4bd0 — 6.9:1
 *  light.accent #2f4bd0 — 6.9:1 on card
 *
 * Tone: the palette stays flat and calm on purpose — no gradients, no
 * celebration colors; the one loud accent is reserved for crisis help.
 */
import { useColorScheme } from "react-native";

export interface ThemeColors {
  /** App background. */
  bg: string;
  /** Raised surfaces: cards, inputs, nav buttons. */
  card: string;
  /** Recessed panels inside cards (evidence panel, re-auth card). */
  cardDeep: string;
  /** Hairlines and dividers. */
  border: string;
  /** Primary text. */
  text: string;
  /** Body / secondary text. */
  body: string;
  /** Meta text and footnotes — safety fine print lives here, so this is
   *  contractually ≥ 4.5:1 on BOTH bg and card (see header). */
  muted: string;
  /** Input placeholders (same contrast duty as muted). */
  placeholder: string;
  /** Links, kind labels, inline affordances. */
  accent: string;
  /** Primary button fill — white labels sit on this. */
  primary: string;
  /** Non-text fills only (progress bar, switch track): decorative, never
   *  used behind text. */
  primaryBright: string;
  /** Text on primary/danger fills. */
  onPrimary: string;
  /** Destructive button fill. */
  danger: string;
  /** Error text. */
  error: string;
  /** Positive evidence badge / upward spark bars. */
  success: string;
  /** Downward spark bars (decorative). */
  sparkDown: string;
  /** The crisis-help surface: deliberately distinct from ordinary cards so
   *  "get help" never reads as just another nav row. */
  helpBg: string;
}

export interface Theme {
  dark: boolean;
  colors: ThemeColors;
  spacing: {
    xs: number; sm: number; md: number; lg: number; xl: number; xxl: number; xxxl: number;
  };
  radius: { sm: number; md: number; lg: number; xl: number };
  type: {
    display: { fontSize: number; fontWeight: "700" };
    question: { fontSize: number; fontWeight: "600"; lineHeight: number };
    titleLg: { fontSize: number; fontWeight: "700"; lineHeight: number };
    title: { fontSize: number; fontWeight: "700" };
    body: { fontSize: number; lineHeight: number };
    bodyLarge: { fontSize: number };
    bodySmall: { fontSize: number; lineHeight: number };
    meta: { fontSize: number };
    caption: { fontSize: number; fontWeight: "700"; letterSpacing: number };
  };
  /** Apple HIG / Android minimum touch target. Text links that cannot grow
   *  a 44pt box must at least carry touchSlop as hitSlop. */
  minTouch: number;
  touchSlop: { top: number; bottom: number; left: number; right: number };
}

const scales = {
  spacing: { xs: 4, sm: 8, md: 12, lg: 16, xl: 20, xxl: 24, xxxl: 32 },
  radius: { sm: 3, md: 10, lg: 12, xl: 14 },
  type: {
    display: { fontSize: 34, fontWeight: "700" as const },
    question: { fontSize: 22, fontWeight: "600" as const, lineHeight: 30 },
    titleLg: { fontSize: 20, fontWeight: "700" as const, lineHeight: 27 },
    title: { fontSize: 17, fontWeight: "700" as const },
    body: { fontSize: 15, lineHeight: 21 },
    bodyLarge: { fontSize: 16 },
    bodySmall: { fontSize: 13, lineHeight: 18 },
    meta: { fontSize: 12 },
    caption: { fontSize: 11, fontWeight: "700" as const, letterSpacing: 1 },
  },
  minTouch: 44,
  touchSlop: { top: 12, bottom: 12, left: 12, right: 12 },
};

export const darkTheme: Theme = {
  dark: true,
  colors: {
    bg: "#0f1115",
    card: "#1a1e26",
    cardDeep: "#141821",
    border: "#222733",
    text: "#e8eaf0",
    body: "#b6bdc9",
    muted: "#8a91a3",
    placeholder: "#8a91a3",
    accent: "#7f9bff",
    primary: "#3b5bdb",
    primaryBright: "#4f7cff",
    onPrimary: "#ffffff",
    danger: "#c0392b",
    error: "#ff6b6b",
    success: "#59c98a",
    sparkDown: "#e06c75",
    helpBg: "#242a38",
  },
  ...scales,
};

export const lightTheme: Theme = {
  dark: false,
  colors: {
    bg: "#f5f6fa",
    card: "#ffffff",
    cardDeep: "#eef0f6",
    border: "#d5dae4",
    text: "#161a22",
    body: "#3d4453",
    muted: "#5a6272",
    placeholder: "#5a6272",
    accent: "#2f4bd0",
    primary: "#2f4bd0",
    primaryBright: "#3b5bdb",
    onPrimary: "#ffffff",
    danger: "#b03525",
    error: "#c92f22",
    success: "#187a41",
    sparkDown: "#c64650",
    helpBg: "#e4e9f5",
  },
  ...scales,
};

/** The active theme: follows the OS color scheme, dark by default (and for
 *  any unrecognized scheme value). */
export function useTheme(): Theme {
  return useColorScheme() === "light" ? lightTheme : darkTheme;
}

src/unlockProof.ts.source:
/**
 * Offline unlock proof (C1 fix).
 *
 * The old offline-unlock path derived keys from the password and a cached
 * salt and unlocked the vault with NO verification — any string "unlocked"
 * the app offline, and a mistyped password then encrypted new entries
 * under a wrong data key (permanently undecryptable).
 *
 * At every ONLINE login we seal a fixed marker under the data key. Offline
 * unlock now proves the password: derive, try to open the seal, and only
 * unlock on success. A wrong password fails the AEAD authentication.
 *
 * Threat-model note: this makes the device itself an offline oracle for
 * password GUESSES — that trade-off is inherent to any local unlock and
 * is bounded by PBKDF2(600k) per guess plus a deliberate delay on
 * failure. The seal reveals nothing about the key beyond guess correctness.
 */
import AsyncStorage from "@react-native-async-storage/async-storage";
import { buildAad, decrypt, encrypt } from "./crypto/envelope";

const proofKey = (userId: string): string => `@mindpattern/unlockproof_${userId}`;
const PROOF_PLAINTEXT = Buffer.from("mindpattern-unlock-proof/v1", "utf8");

/** Call exactly once after a VERIFIED online login (or registration):
 *  seals the marker under the account's data key. */
export async function storeUnlockProof(dataKey: Buffer, userId: string): Promise<void> {
  const blob = encrypt(dataKey, PROOF_PLAINTEXT, buildAad("unlockproof", userId));
  await AsyncStorage.setItem(proofKey(userId), blob.toString("base64"));
}

export type ProofResult = "ok" | "wrong" | "absent";

/** Prove a derived data key offline. */
export async function verifyUnlockProof(dataKey: Buffer, userId: string): Promise<ProofResult> {
  const raw = await AsyncStorage.getItem(proofKey(userId));
  if (!raw) return "absent";
  try {
    const plain = decrypt(dataKey, Buffer.from(raw, "base64"), buildAad("unlockproof", userId));
    return plain.equals(PROOF_PLAINTEXT) ? "ok" : "wrong";
  } catch {
    return "wrong";
  }
}

export async function clearUnlockProof(userId: string): Promise<void> {
  await AsyncStorage.removeItem(proofKey(userId));
}

export async function unlockProofExists(userId: string): Promise<boolean> {
  return (await AsyncStorage.getItem(proofKey(userId))) !== null;
}

