src/crypto/engine.ts.source:
/**
 * Crypto backend seam.
 *
 * The app runs on react-native-quick-crypto. Tools and tests run under
 * Node, where quick-crypto cannot resolve — there the identical API surface
 * of node:crypto backs the same modules. This is what lets the vector
 * verifier and vitest suite execute the REAL shipping crypto code instead
 * of a parallel reimplementation that could silently drift.
 */

export interface CryptoEngine {
  randomBytes(size: number): Buffer;
  pbkdf2Sync(password: string | Buffer, salt: Buffer, iterations: number, keylen: number, digest: string): Buffer;
  /** The async form: quick-crypto (>= 0.7) runs the derivation on its
   *  native JSI worker and node:crypto on the libuv thread pool — both keep
   *  the JS thread free, unlike pbkdf2Sync's ~100-400ms freeze at 600k
   *  iterations. Node-style callback; a missing derivedKey on success is
   *  treated as an error by the caller. */
  pbkdf2(
    password: string | Buffer,
    salt: Buffer,
    iterations: number,
    keylen: number,
    digest: string,
    callback: (err: Error | null, derivedKey?: Buffer) => void,
  ): void;
  hkdfSync(digest: string, ikm: Buffer, salt: Buffer, info: Buffer, length: number): ArrayBuffer;
  createCipheriv(algorithm: string, key: Buffer, iv: Buffer): {
    setAAD(aad: Buffer): unknown;
    update(data: Buffer): Buffer;
    final(): Buffer;
    getAuthTag(): Buffer;
  };
  createDecipheriv(algorithm: string, key: Buffer, iv: Buffer): {
    setAuthTag(tag: Buffer): unknown;
    setAAD(aad: Buffer): unknown;
    update(data: Buffer): Buffer;
    final(): Buffer;
  };
}

// Metro (React Native) and tsc-emitted CJS provide require(); declare it
// locally so typechecking does not depend on @types/node.
declare const require: ((id: string) => unknown) | undefined;

type RequireFn = (id: string) => unknown;

// vite-node, Metro and every CJS host provide require(). An ESM-only host
// does not, and the bare reference below throws ReferenceError at import —
// loud on purpose: a silently wrong crypto backend would be worse.
function hostRequire(): RequireFn {
  return require as RequireFn;
}

/**
 * Resolve the crypto backend. The require function is injectable so every
 * branch is testable: on a device it returns the native quick-crypto addon;
 * under plain-node tools the addon fails to load and node:crypto implements
 * the same API surface.
 */
export function loadEngine(req: RequireFn = hostRequire()): CryptoEngine {
  try {
    return req("react-native-quick-crypto") as CryptoEngine;
  } catch {
    return req("node:crypto") as CryptoEngine;
  }
}

export const engine: CryptoEngine = loadEngine();

tests/smallModules.pins.test.ts.source:
/**
 * Deep-mutation pins for the small modules (2026-09-15 Stryker campaign):
 *  - secureStore: an envelope whose `c` is a byte ARRAY reads as absent (the
 *    typeof-string guard is real), and a v1-path failure falls into the
 *    legacy path — pinned by an envelope whose JSON text itself base64-
 *    decodes to a valid forgery-free blob (only the emptied catch would
 *    return it),
 *  - unlockProof: the sealed marker plaintext is exactly
 *    "mindpattern-unlock-proof/v1", and unlockProofExists is really false
 *    when nothing is stored,
 *  - entryId: the + and / base64url mappings with stubbed engine bytes,
 *  - onboarding: a fresh module starts with NO pending onboarding, and the
 *    persisted seen sentinel is exactly "1",
 *  - genericQuestions: the exact per-date pick (djb2 ×33),
 *  - kdf: the async derivation accepts an exactly-8-byte salt,
 *  - envelope: a supplied nonce of the wrong length fails loudly.
 *
 * Equivalents are suppressed at the source (secureStore's deviceKey cache
 * fast path, the utf8 encoding literal; entryId's unreachable padding
 * strip; genericQuestions' loop bound — see those files).
 */
// @ts-nocheck

import { beforeEach, describe, expect, it, vi } from "vitest";
import storage from "./helpers/storageMock";

const { encrypt, decrypt, buildAad } = await import("../src/crypto/envelope");
const { deriveMasterKeyAsync } = await import("../src/crypto/kdf");

beforeEach(() => {
  storage.__reset();
});

/** A fresh secureStore module graph backed by a KNOWN device key. */
async function freshSecureStore(key: Buffer) {
  vi.resetModules();
  const freshStorage = (await import("@react-native-async-storage/async-storage")).default as typeof storage;
  await freshStorage.setItem("@mindpattern/device_k", key.toString("base64"));
  const mod = await import("../src/secureStore");
  return { freshStorage, secureStore: mod.secureStore };
}

describe("secureStore pins", () => {
  it("an envelope whose c is a byte ARRAY reads as absent, not as decryptable", async () => {
    const key = Buffer.alloc(32, 9);
    const { freshStorage, secureStore } = await freshSecureStore(key);
    // A perfectly valid ciphertext — planted under c as JSON numbers.
    const blob = encrypt(key, Buffer.from("array-envelope-secret"));
    await freshStorage.setItem("k", JSON.stringify({ v: 1, c: Array.from(blob) }));
    // typeof c !== "string" must hold the line: the mutant would feed the
    // array through Buffer.from(numbers) and return the plaintext.
    expect(await secureStore.getItem("k")).toBeNull();
  });

  it("an emptied v1 catch falls through to the legacy path — pinned with a self-decoding envelope", async () => {
    // Construct an envelope string whose base64-valid characters ("v1c" +
    // c) decode to a REAL ciphertext: nonce chosen so the first three
    // base64 chars of the blob are exactly "v1c".
    const key = Buffer.alloc(32, 9);
    const { freshStorage, secureStore } = await freshSecureStore(key);
    const nonce = Buffer.from([0xbf, 0x57, 0x3f, 0, 0, 0, 0, 0, 0, 0, 0, 0]);
    const blob = encrypt(key, Buffer.from("forged-legacy-secret"), undefined, nonce);
    const s = blob.toString("base64");
    expect(s.startsWith("v1c")).toBe(true); // the construction holds
    const c = s.slice(3);
    const raw = `{"v":1,"c":"${c}"}`;
    // Precondition 1: c on its own must fail decryption (so the v1 path
    // throws and the catch decides the outcome).
    expect(() => decrypt(key, Buffer.from(c, "base64"))).toThrow();
    // Precondition 2: the envelope's own filtered characters decode to the
    // valid blob — exactly what the legacy path would feed to decrypt if
    // the catch were emptied.
    expect(decrypt(key, Buffer.from(raw.replace(/[^A-Za-z0-9+/=]/g, ""), "base64")).toString("utf8")).toBe(
      "forged-legacy-secret",
    );
    await freshStorage.setItem("k", raw);
    // The intact catch returns null; the emptied-catch mutant falls through
    // to the legacy path and returns the forged-looking plaintext.
    expect(await secureStore.getItem("k")).toBeNull();
  });
});

describe("unlockProof pins", () => {
  // The secureStore tests above call vi.resetModules(), so every later test
  // must import the storage helper and the module under test from the SAME
  // fresh module graph (the top-level `storage` binding points at the old,
  // orphaned instance).
  it("the sealed marker is exactly 'mindpattern-unlock-proof/v1'", async () => {
    const s = (await import("./helpers/storageMock")).default;
    const { storeUnlockProof } = await import("../src/unlockProof");
    const dataKey = Buffer.alloc(32, 7);
    await storeUnlockProof(dataKey, "u9");
    const raw = await s.getItem("@mindpattern/unlockproof_u9");
    expect(raw).not.toBeNull();
    const plain = decrypt(dataKey, Buffer.from(raw, "base64"), buildAad("unlockproof", "u9"));
    expect(plain.toString("utf8")).toBe("mindpattern-unlock-proof/v1");
  });

  it("unlockProofExists is genuinely false when nothing is stored (and after clear)", async () => {
    const s = (await import("./helpers/storageMock")).default;
    await s.__reset();
    const { storeUnlockProof, clearUnlockProof, unlockProofExists } = await import("../src/unlockProof");
    expect(await unlockProofExists("u-none")).toBe(false);
    const dataKey = Buffer.alloc(32, 7);
    await storeUnlockProof(dataKey, "u1");
    expect(await unlockProofExists("u1")).toBe(true);
    await clearUnlockProof("u1");
    expect(await unlockProofExists("u1")).toBe(false);
  });
});

describe("entryId pins", () => {
  it("maps + and / to - and _ exactly (stubbed engine bytes)", async () => {
    const { engine } = await import("../src/crypto/engine");
    const { newClientEntryId } = await import("../src/entryId");
    // base64 of [0xfb,0,0, 0xff,0,0, 0,0,0] is "+wAA/wAAAAAA" — one of each
    // special character, and no padding (9 bytes is a multiple of 3).
    const original = engine.randomBytes;
    try {
      engine.randomBytes = (() => Buffer.from([0xfb, 0, 0, 0xff, 0, 0, 0, 0, 0])) as typeof engine.randomBytes;
      expect(newClientEntryId("2026-01-31")).toBe("e-2026-01-31--wAA_wAAAAAA");
    } finally {
      engine.randomBytes = original;
    }
  });
});

describe("onboarding pins", () => {
  it("a fresh module starts with NO pending onboarding", async () => {
    vi.resetModules();
    const fresh = await import("../src/onboarding");
    expect(fresh.takePendingOnboarding()).toBe(false);
    fresh.queueOnboarding();
    expect(fresh.takePendingOnboarding()).toBe(true);
    expect(fresh.takePendingOnboarding()).toBe(false);
  });

  it("recordOnboardingSeen persists exactly the '1' sentinel", async () => {
    const s = (await import("./helpers/storageMock")).default;
    const { recordOnboardingSeen } = await import("../src/onboarding");
    await recordOnboardingSeen("user-1");
    expect(await s.getItem("@mindpattern/onboarding_seen_user-1")).toBe("1");
  });
});

describe("genericQuestions pins", () => {
  it("the djb2×33 rotation picks the exact pool slot per date", async () => {
    const { genericQuestionForDate } = await import("../src/genericQuestions");
    expect(genericQuestionForDate("2026-09-07")).toBe("If today had a title, what would it be?");
    expect(genericQuestionForDate("2026-09-08")).toBe("When did you feel most like yourself today?");
    expect(genericQuestionForDate("2026-10-01")).toBe("What's one small thing that went right today?");
  });
});

describe("kdf and envelope pins", () => {
  it("deriveMasterKeyAsync accepts an exactly-8-byte salt (the floor is inclusive)", async () => {
    const master = await deriveMasterKeyAsync("pw", Buffer.alloc(8, 1), 1);
    expect(master).toHaveLength(32);
    expect(master.equals(await deriveMasterKeyAsync("pw", Buffer.alloc(8, 1), 1))).toBe(true);
  });

  it("a supplied nonce of the wrong length fails with the exact message", () => {
    const key = Buffer.alloc(32, 1);
    expect(() => encrypt(key, Buffer.from("x"), undefined, Buffer.alloc(11))).toThrow(/nonce must be 12 bytes/);
    expect(() => encrypt(key, Buffer.from("x"), undefined, Buffer.alloc(13))).toThrow(/nonce must be 12 bytes/);
  });
});

tests/client.pins.test.ts.source:
/**
 * Deep-mutation pins for the API client (2026-09-15 Stryker campaign).
 *
 * Each block kills specific surviving mutants (see /tmp/surv_api__client.ts.txt):
 *  - the exact AsyncStorage key names session material lives under,
 *  - queue_quarantine/queue_rejected being origin-bound on a server switch,
 *  - the first-save (previous === null) case keeping the session,
 *  - insecure-HTTP consent recorded only for insecure servers (&& not ||),
 *  - sanitizeDetail regex vectors: scheme URLs at string start, "xhttp://",
 *    and a URL-like fragment after "https://" whitespace,
 *  - parseRetryAfter boundaries: negative, Infinity, and the exact-0 vector
 *    whose Date.parse fallback differs ("0e0" parses as NaN, "0" as year 2000),
 *  - the 401 hook firing ONLY on 401s that carried a token,
 *  - Retry-After read ONLY on 429 and only through a real headers object,
 *  - getCachedSalt refusing a non-string s, and clearCachedSalt really wiping.
 */
// @ts-nocheck

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import storage from "./helpers/storageMock";
import {
  api,
  DEFAULT_BASE_URL,
  detailToMessage,
  getInsecureConsentUrl,
  isInsecureHttpAllowed,
  parseRetryAfter,
  setBaseUrl,
  setUnauthorizedHandler,
} from "../src/api/client";

const jsonResponse = (body: unknown, status = 200, url = DEFAULT_BASE_URL): Response => {
  const response = new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json" } });
  Object.defineProperty(response, "url", { value: url });
  return response;
};

beforeEach(() => {
  storage.__reset();
  vi.stubGlobal("fetch", vi.fn(async () => jsonResponse({ ok: true })));
});

afterEach(() => {
  vi.unstubAllGlobals();
  setUnauthorizedHandler(null);
});

describe("client pins: session storage key names", () => {
  it("user id and username land under their exact AsyncStorage keys (encrypted wrappers)", async () => {
    await api.setSession("tok", "u-1", "kim");
    // secureStore wraps the values, but they must exist under the canonical
    // keys — an emptied key constant would store them under "" instead.
    expect(await storage.getItem("@mindpattern/user_id")).not.toBeNull();
    expect(await storage.getItem("@mindpattern/username")).not.toBeNull();
  });
});

describe("client pins: origin-bound local state on server switch", () => {
  it("queue quarantine/rejected stores are wiped with the origin, unrelated keys survive", async () => {
    await setBaseUrl("https://old.example.com");
    await storage.setItem("@mindpattern/queue_quarantine", "q");
    await storage.setItem("@mindpattern/queue_rejected", "r");
    await storage.setItem("@mindpattern/unrelated", "keep-me");

    expect(await setBaseUrl("https://new.example.com")).toBeNull();

    // The queue's quarantine/rejected markers belong to the old origin: one
    // server's poisoning must not steer the next server's flush.
    expect(await storage.getItem("@mindpattern/queue_quarantine")).toBeNull();
    expect(await storage.getItem("@mindpattern/queue_rejected")).toBeNull();
    // …while foreign keys are untouched (the filter is a whitelist).
    expect(await storage.getItem("@mindpattern/unrelated")).toBe("keep-me");
  });
});

describe("client pins: first URL save", () => {
  it("saving a base URL with NO previous one keeps the stored session (no phantom origin change)", async () => {
    await api.setSession("tok-keep", "u-1", "alice");
    expect(await api.isLoggedIn()).toBe(true);
    // First-ever save: previous === null is NOT an origin change — the
    // session must survive it (originChanged would be forced true otherwise).
    expect(await setBaseUrl("https://first.example.com")).toBeNull();
    expect(await api.isLoggedIn()).toBe(true);
    expect(await api.getUserId()).toBe("u-1");
  });
});

describe("client pins: insecure consent records only insecure servers", () => {
  it("a SECURE url saved with allowInsecure records NO consent", async () => {
    expect(await setBaseUrl("https://secure.example.com", { allowInsecure: true })).toBeNull();
    // Consent is the exact insecure URL or the literal "0" — never a secure
    // URL (the && must not degrade to ||, which would bless any save).
    expect(await storage.getItem("@mindpattern/insecure_http_ok")).toBe("0");
    expect(await isInsecureHttpAllowed()).toBe(false);
    expect(await getInsecureConsentUrl()).toBeNull();
  });
});

describe("client pins: sanitizeDetail regex vectors", () => {
  it("a URL fragment after scheme-whitespace is NOT stripped (the \\S is load-bearing)", () => {
    // "https://" followed by whitespace matches neither the http nor the
    // generic scheme regex (both require \\S+ right after "://") — replacing
    // \\S with \\s here would swallow the "https://" and change the message.
    expect(detailToMessage("see https:// evil.example now", 400)).toBe("see https:// evil.example now");
  });

  it("an 'xhttp://' URL loses only its http:// part — the 'x' prefix survives", () => {
    // The http(s) regex matches mid-token, so "x" is left behind; only the
    // later generic-scheme pass could eat the whole token (https-only mutant).
    expect(detailToMessage("go xhttp://a now", 400)).toBe("go x now");
  });

  it("a scheme URL at the very start of the message is stripped", () => {
    // With no preceding character, [^a-z]-style mutations cannot ride an
    // earlier non-letter and the strip must still happen.
    expect(detailToMessage("mywallet://transfer?to=evil now", 400)).toBe("now");
  });
});

describe("client pins: parseRetryAfter boundaries", () => {
  it("negative seconds clamp to 0 via the date fallback — never a negative retryAfterMs", () => {
    // "-5" fails seconds >= 0, and V8's Date.parse("-5") is a past date that
    // clamps to 0; a || / >=0→true mutant would return -5000 instead.
    expect(parseRetryAfter("-5")).toBe(0);
    // Infinity is not finite and not a date: undefined, never the ceiling.
    expect(parseRetryAfter("Infinity")).toBeUndefined();
  });

  it("an exact zero delays by exactly 0ms (>= is strict at the boundary)", () => {
    // "0e0" numeric-parses to 0 but is NOT an HTTP-date (NaN), unlike "0"
    // (which V8 reads as year 2000 and clamps back to 0) — so only the
    // seconds branch can produce 0 here.
    expect(parseRetryAfter("0e0")).toBe(0);
  });
});

describe("client pins: 401 hook gating", () => {
  it("a non-401 error that carried a token does NOT fire the session-death hook", async () => {
    const handler = vi.fn();
    setUnauthorizedHandler(handler);
    await api.setSession("tok-1", "u-1", "alice");
    vi.mocked(fetch).mockResolvedValue(jsonResponse({ detail: "boom" }, 500));
    await expect(api.insights()).rejects.toMatchObject({ status: 500 });
    expect(handler).not.toHaveBeenCalled();
  });
});

describe("client pins: Retry-After is read only on 429 with a real headers object", () => {
  it("a non-429 error with a Retry-After header carries no retryAfterMs", async () => {
    const response = jsonResponse({ detail: "slow down" }, 500);
    response.headers.set("retry-after", "30");
    vi.mocked(fetch).mockResolvedValue(response);
    await expect(api.meta()).rejects.toMatchObject({ status: 500, retryAfterMs: undefined });
  });

  it("a 429 without any headers object still maps to a 429 ApiError (no TypeError)", async () => {
    vi.mocked(fetch).mockResolvedValue({ ok: false, status: 429, url: DEFAULT_BASE_URL, json: async () => ({}) } as never);
    await expect(api.meta()).rejects.toMatchObject({ status: 429, retryAfterMs: undefined });
  });
});

describe("client pins: salt cache record shape", () => {
  it("a v1 record with a non-string s is refused (never returned raw)", async () => {
    await storage.setItem("@mindpattern/salt_nonstring", JSON.stringify({ v: 1, o: DEFAULT_BASE_URL, s: 5 }));
    expect(await api.getCachedSalt("nonstring")).toBeNull();
  });

  it("clearCachedSalt really removes the cached record", async () => {
    await api.cacheSalt("kim", "c2FsdA==");
    expect(await api.getCachedSalt("kim")).toBe("c2FsdA==");
    await api.clearCachedSalt("kim");
    expect(await api.getCachedSalt("kim")).toBeNull();
  });
});

