    await pressLabel(root, "an ordinary entry");
    await pressLabel(root, "Need help now? Crisis resources");
    await pressLabel(root, "Edit this entry");
    await pressLabel(root, "Need help now? Crisis resources");
    expect(nav.navigate.mock.calls).toEqual([["Crisis"], ["Crisis"], ["Crisis"]]);
