/**
 * crisisDetect: the on-device, pre-encryption crisis-language matcher.
 * Pins every phrase family (a silent regression here means a missed
 * crisis), the case/whitespace tolerance of quick typing, and — just as
 * important — that everyday journal text does NOT trip it.
 */
import { describe, expect, it } from "vitest";
import { detectCrisisLanguage } from "../src/crisisDetect";

describe("detectCrisisLanguage — true positives", () => {
  it.each([
    // Direct suicidal statements (each phrase family).
    "I keep thinking about how to kill myself",
    "i have been thinking about killing myself",
    "the note mentioned suicide twice",
    "I feel suicidal tonight",
    "I want to die",
    "i wanted to die back then",
    "I just wanna die sometimes",
    "I wish I was dead",
    "I wish i were dead",
    // Ending it.
    "I just want to end it all",
    "thinking about ending it all",
    "I want to end my life",
    "plans for ending my life",
    "thinking about how to take my own life",
    "afraid I will take my life",
    // Self-harm.
    "I keep slipping back into self harm",
    "the self-harm started again",
    "i am self harming again",
    "I want to hurt myself",
    "I keep hurting myself",
    // Hopelessness phrases.
    "there is no reason to live anymore",
    "no reason to go on",
    "I can't go on like this",
    "i cant go on",
    "I cannot go on anymore",
    "everyone would be better off without me",
    "I don't want to be here",
    "i dont want to live",
    "I do not want to exist",
    // M2 additions: purpose-in-life, be-alive, death-wish gerunds/infinitives,
    // and the cut-myself self-harm family.
    "there is nothing to live for",
    "i have nothing to live for anymore",
    "I don't want to be alive",
    "i do not want to be alive",
    "wanting to die more days than not",
    "i keep wanting to die",
    "i feel like dying",
    "lately everything feels like dying inside",
    "wish i could die",
    "I wish I could die in my sleep",
    "i cut myself again",
    "i have been cutting myself",
  ])("fires on %j", (text) => {
    expect(detectCrisisLanguage(text)).toBe(true);
  });

  // iOS Smart Punctuation substitutes U+2019 for ASCII ' by default — every
  // apostrophe-tolerant family must fire on BOTH spellings or iPhone typing
  // silently misses detection.
  const CURLY = "\u2019";
  it.each([
    `I can${CURLY}t go on`,
    `i don${CURLY}t want to live`,
    `I don${CURLY}t want to be here`,
    `don${CURLY}t want to be alive`,
    `i don${CURLY}t want to exist`,
  ])("fires on the curly-apostrophe (U+2019) variant %j", (text) => {
    expect(detectCrisisLanguage(text)).toBe(true);
  });

  it("still fires on the ASCII and dropped-apostrophe variants", () => {
    expect(detectCrisisLanguage("I can't go on")).toBe(true);
    expect(detectCrisisLanguage("i cant go on")).toBe(true);
    expect(detectCrisisLanguage("I cannot go on")).toBe(true);
    expect(detectCrisisLanguage("i dont want to live")).toBe(true);
    expect(detectCrisisLanguage("I do not want to live")).toBe(true);
  });

  it("is case-insensitive, including ALL CAPS and mixed case", () => {
    expect(detectCrisisLanguage("I WANT TO DIE")).toBe(true);
    expect(detectCrisisLanguage("I wAnT tO eNd It AlL")).toBe(true);
    expect(detectCrisisLanguage("SUICIDAL")).toBe(true);
  });

  it("fires when the phrase is buried in a longer entry", () => {
    const entry =
      "Work was fine and the kids were sweet at dinner, but if I am honest " +
      "with myself I keep coming back to the thought that they would be " +
      "better off without me. I will try to sleep now.";
    expect(detectCrisisLanguage(entry)).toBe(true);
  });

  it("tolerates extra whitespace and newlines inside phrases", () => {
    expect(detectCrisisLanguage("I want  to\n die")).toBe(true);
    expect(detectCrisisLanguage("no  reason\tto live")).toBe(true);
  });
});

describe("detectCrisisLanguage — true negatives", () => {
  it.each([
    // Ordinary journal text.
    "Had a good day. Walked the dog, finished the report, called mom.",
    "The assessment at work was brutal but I passed it.",
    "That workout killed my legs — I can barely walk.",
    "This traffic is killing me.",
    "My boss would kill me if I missed that deadline.",
    "I was dying of laughter at the show.",
    "I'm dead tired after the red-eye.",
    "I killed it at the presentation today.",
    "Feeling anxious about the move but also excited.",
    "I want to diet again starting Monday.",
    "The exam ends, it all comes down to Friday.",
    // Near-misses for the M2 additions.
    "I have nothing to lose.",
    "the new hire has nothing to live up to",
    "i do want to be alive",
    "i want to be alive for my kids",
    "I wish I could fly",
    "feels like a dying art form",
    "i need to cut my hair this weekend",
    "his cutting remarks stung all day",
  ])("does NOT fire on %j", (text) => {
    expect(detectCrisisLanguage(text)).toBe(false);
  });

  it("accepts the deliberate false positive: even 'suicide prevention' context", () => {
    // "suicide" is high-signal enough that the matcher fires on any use of
    // the word — the cost is one gentle dialog, the benefit is no misses.
    expect(detectCrisisLanguage("We discussed suicide prevention policy in class today.")).toBe(true);
  });

  it("accepts the documented false positives: benign 'cut myself' / 'feel like dying' contexts", () => {
    // A clean context distinction ("shaving", "chopping onions", gym
    // hyperbole) would be an incomplete blocklist pretending to be
    // precision — see the crisisDetect header. The conservative contract
    // pays one gentle dialog instead of risking a miss.
    expect(detectCrisisLanguage("I cut myself shaving this morning")).toBe(true);
    expect(detectCrisisLanguage("I feel like dying after that workout")).toBe(true);
  });

  it("does not fire on empty or whitespace-only input", () => {
    expect(detectCrisisLanguage("")).toBe(false);
    expect(detectCrisisLanguage("   \n\t  ")).toBe(false);
  });

  it("does not fire on partial-word lookalikes", () => {
    expect(detectCrisisLanguage("the assessment was nothing relevant")).toBe(false);
    expect(detectCrisisLanguage("a dying breed of craftsman")).toBe(false);
    expect(detectCrisisLanguage("the suicidology textbook")).toBe(false);
  });
});

tests/components.pins.test.tsx.source:
/**
 * Deep-mutation pins for the shared components (2026-09-15 Stryker campaign):
 * buttons.tsx (PrimaryButton / GhostButton / CrisisHelpButton) and
 * InlineStatus.tsx (InlineStatus / NoticeChip).
 *
 * Every survivor is pinned by asserting the EXACT style array on the
 * TouchableOpacity / View / Text node it belongs to — including the literal
 * `false` entries the `&&` overlays produce — plus the accessibility-label
 * routing (`??` vs `&&`) and InlineStatus's null-message / tone gates.
 */
// @ts-nocheck

import { describe, expect, it, vi } from "vitest";
import React from "react";
import { ActivityIndicator, Text, TouchableOpacity, View } from "react-native";

const { PrimaryButton, GhostButton, CrisisHelpButton } = await import("../src/components/buttons");
const { InlineStatus, NoticeChip } = await import("../src/components/InlineStatus");
const { render, textOf, touchableByLabel } = await import("./helpers/rtr");

describe("PrimaryButton pins: the exact style-array contract", () => {
  it("enabled: primary base + fill overlay + the literal false (NO dimmed entry)", async () => {
    const root = await render(<PrimaryButton label="Save entry" onPress={() => {}} />);
    const btn = touchableByLabel(root, "Save entry");
    expect(btn.props.style).toEqual([
      { borderRadius: 10, padding: 16, alignItems: "center", justifyContent: "center" },
      { backgroundColor: "#3b5bdb", minHeight: 44 },
      false,
    ]);
  });

  it("busy: the dimmed overlay {opacity: 0.6} is the third array entry", async () => {
    const root = await render(<PrimaryButton label="Save entry" onPress={() => {}} busy />);
    const btn = root.root.findAllByType(TouchableOpacity)[0];
    expect(btn.props.style).toEqual([
      { borderRadius: 10, padding: 16, alignItems: "center", justifyContent: "center" },
      { backgroundColor: "#3b5bdb", minHeight: 44 },
      { opacity: 0.6 },
    ]);
    expect(root.root.findAllByType(ActivityIndicator)).toHaveLength(1);
  });

  it("disabled: dimmed too (the overlay keys off isDisabled, not just busy)", async () => {
    const root = await render(<PrimaryButton label="Save entry" onPress={() => {}} disabled />);
    const btn = root.root.findAllByType(TouchableOpacity)[0];
    expect((btn.props.style as unknown[])[2]).toEqual({ opacity: 0.6 });
    expect(btn.props.disabled).toBe(true);
  });
});

describe("GhostButton pins: centering, touch target, label routing", () => {
  it("default center=true: ghost base + centered + minHeight in order", async () => {
    const root = await render(<GhostButton label="Switch mode" onPress={() => {}} />);
    const btn = touchableByLabel(root, "Switch mode");
    expect(btn.props.style).toEqual([{ padding: 12 }, { alignItems: "center" }, { minHeight: 44 }]);
    // The default accessibilityLabel IS the visible label (?? routing).
    expect(btn.props.accessibilityLabel).toBe("Switch mode");
  });

  it("center={false}: the centered entry is the literal false, never the style", async () => {
    const root = await render(<GhostButton label="Support resources" onPress={() => {}} center={false} />);
    const btn = touchableByLabel(root, "Support resources");
    expect(btn.props.style).toEqual([{ padding: 12 }, false, { minHeight: 44 }]);
  });

  it("an explicit accessibilityLabel overrides the visible label (??, not &&)", async () => {
    const root = await render(
      <GhostButton label="Get help" onPress={() => {}} accessibilityLabel="Get help — crisis resources" />,
    );
    expect(touchableByLabel(root, "Get help").props.accessibilityLabel).toBe("Get help — crisis resources");
  });
});

describe("CrisisHelpButton pins", () => {
  it("the help surface and its label text carry their exact styles", async () => {
    const root = await render(<CrisisHelpButton onPress={() => {}} />);
    const btn = touchableByLabel(root, "Need help now? Crisis resources");
    expect(btn.props.style).toEqual([
      { padding: 16, alignItems: "center", justifyContent: "center" },
      { backgroundColor: "#242a38", borderRadius: 10, minHeight: 44 },
    ]);
    const label = root.root.findAllByType(Text)[0];
    expect(label.props.style).toEqual([{ fontWeight: "700" }, { color: "#e8eaf0", fontSize: 14 }]);
  });
});

describe("InlineStatus pins", () => {
  it("a null message renders nothing at all — not even a View", async () => {
    const empty = await render(<InlineStatus message={null} />);
    expect(empty.root.findAllByType(View)).toHaveLength(0);
    expect(empty.root.findAllByType(Text)).toHaveLength(0);
    expect(textOf(empty)).toBe("");
  });

  it("the status line: exact surface array and the DEFAULT ok tone's success color", async () => {
    const root = await render(<InlineStatus message="Saved ✓" />);
    const view = root.root.findAll((n) => n.props.accessibilityLiveRegion === "polite")[0];
    expect(view).toBeDefined();
    expect(view.props.style).toEqual([
      { paddingVertical: 10, paddingHorizontal: 14, alignItems: "center" },
      { backgroundColor: "#141821", borderRadius: 10 },
    ]);
    // tone defaults to "ok" → success color (a "" default or a false tone
    // condition would render the neutral muted color instead).
    expect(root.root.findAllByType(Text)[0].props.style).toEqual({ color: "#59c98a", fontSize: 13 });
  });

  it("the neutral tone renders the muted color exactly", async () => {
    const root = await render(<InlineStatus message="Saved — will sync when online" tone="neutral" />);
    expect(root.root.findAllByType(Text)[0].props.style).toEqual({ color: "#8a91a3", fontSize: 13 });
  });
});

describe("NoticeChip pins", () => {
  it("the chip surface and its text carry their exact styles", async () => {
    const root = await render(<NoticeChip text="Draft restored" />);
    const view = root.root.findAll((n) => n.props.accessibilityRole === "text")[0];
    expect(view).toBeDefined();
    expect(view.props.style).toEqual([
      { alignSelf: "flex-start", paddingVertical: 6, paddingHorizontal: 12 },
      { backgroundColor: "#1a1e26", borderRadius: 12 },
    ]);
    expect(root.root.findAllByType(Text)[0].props.style).toEqual({ color: "#8a91a3", fontSize: 12 });
  });
});

tests/reauth.test.ts.source:
/**
 * H2: password re-authentication for destructive actions. The verifier is
 * only released when the typed password re-derives the vault's own key.
 */
import { beforeEach, describe, expect, it, vi } from "vitest";
import storage from "./helpers/storageMock";

vi.mock("../src/api/client", async () => {
  const { makeApiMock, ApiError } = await import("./helpers/apiMock");
  return { ApiError, api: makeApiMock() };
});

import { deriveKeys } from "../src/crypto/MindPatternCrypto";
import { verifyPasswordForVault, isVerificationFailedError, isSessionExpiredError } from "../src/reauth";
import { vault } from "../src/vault";
import { api, ApiError } from "../src/api/client";

const SALT = Buffer.alloc(16, 3);
const SALT_B64 = SALT.toString("base64"); // the salt the vault keys derive from
const PASSWORD = "correct horse battery staple";

/** Fresh keys per use: vault.lock() zeroizes the shared underlying buffers,
 *  so a module-level singleton would read back as zeros after the first test. */
const freshKeys = (): { masterKey: Buffer; authKey: Buffer; dataKey: Buffer } => deriveKeys(PASSWORD, SALT);

beforeEach(() => {
  storage.__reset();
  vi.mocked(api.getUsername).mockClear();
  vi.mocked(api.getUsername).mockImplementation(async () => "alice");
  vi.mocked(api.getCachedSalt).mockClear();
  vi.mocked(api.getCachedSalt).mockImplementation(async () => SALT_B64);
  vi.mocked(api.saltFor).mockClear();
  vault.lock();
  // The vault holds the keys the CORRECT password derives.
  vault.unlock({ ...freshKeys() });
});

describe("verifyPasswordForVault", () => {
  it("releases the verifier for the correct password", async () => {
    const result = await verifyPasswordForVault(PASSWORD);
    expect(result).toEqual({ ok: true, verifierB64: freshKeys().authKey.toString("base64") });
  });

  it("refuses a wrong password without leaking the verifier", async () => {
    const result = await verifyPasswordForVault("wrong password");
    expect(result).toEqual({ ok: false, reason: "wrong-password" });
  });

  it("refuses when the vault is locked", async () => {
    vault.lock();
    expect(await verifyPasswordForVault(PASSWORD)).toEqual({ ok: false, reason: "locked" });
  });

  it("refuses when no account is stored", async () => {
    vi.mocked(api.getUsername).mockResolvedValue(null);
    expect(await verifyPasswordForVault(PASSWORD)).toEqual({ ok: false, reason: "no-account" });
  });

  it("falls back to fetching the salt online when none is cached", async () => {
    vi.mocked(api.getCachedSalt).mockResolvedValue(null);
    vi.mocked(api.saltFor).mockResolvedValue({ salt: SALT_B64 } as never);
    const result = await verifyPasswordForVault(PASSWORD);
    expect(result).toEqual({ ok: true, verifierB64: freshKeys().authKey.toString("base64") });
    expect(api.cacheSalt).toHaveBeenCalledWith("alice", SALT_B64);
  });

  it("reports offline when no salt is available anywhere", async () => {
    vi.mocked(api.getCachedSalt).mockResolvedValue(null);
    vi.mocked(api.saltFor).mockRejectedValue(new Error("offline") as never);
    expect(await verifyPasswordForVault(PASSWORD)).toEqual({ ok: false, reason: "offline" });
  });

  it("refuses an empty password before touching the vault or the network", async () => {
    expect(await verifyPasswordForVault("")).toEqual({ ok: false, reason: "wrong-password" });
    expect(api.getUsername).not.toHaveBeenCalled();
  });

  it("reports offline when the fetched salt comes back empty", async () => {
    vi.mocked(api.getCachedSalt).mockResolvedValue(null);
    vi.mocked(api.saltFor).mockResolvedValue({ salt: "" } as never);
    expect(await verifyPasswordForVault(PASSWORD)).toEqual({ ok: false, reason: "offline" });
  });

  it("a vault holding a malformed (wrong-length) key never matches", async () => {
    // keysEqual's length guard: a truncated/corrupt key in the vault must
    // fail closed, not crash the comparison.
    vault.lock();
    vault.unlock({ masterKey: Buffer.alloc(32), authKey: Buffer.alloc(16, 9), dataKey: Buffer.alloc(32) });
    expect(await verifyPasswordForVault(PASSWORD)).toEqual({ ok: false, reason: "wrong-password" });
  });

  it("a similar-but-different salt derivation never matches the vault key", async () => {
    // Same password, DIFFERENT salt (the cross-origin poisoning case).
    vi.mocked(api.getCachedSalt).mockResolvedValue(Buffer.alloc(16, 9).toString("base64"));
    expect(await verifyPasswordForVault(PASSWORD)).toEqual({ ok: false, reason: "wrong-password" });
  });
});

describe("verifier-failure classification (403 vs 401)", () => {
  it("403 verification_failed = wrong verifier, vault can stay unlocked", () => {
    expect(isVerificationFailedError(new ApiError(403, "verification failed", "verification_failed"))).toBe(true);
    // Legacy servers without the envelope: status alone carries the meaning.
    expect(isVerificationFailedError(new ApiError(403, "forbidden"))).toBe(true);
    expect(isSessionExpiredError(new ApiError(403, "verification failed", "verification_failed"))).toBe(false);
  });

  it("a 403 with a DIFFERENT code is not a verifier failure", () => {
    expect(isVerificationFailedError(new ApiError(403, "nope", "quota_exceeded"))).toBe(false);
  });

  it("401 = session expired (the vault is already locked by the client hook)", () => {
    expect(isSessionExpiredError(new ApiError(401, "invalid token", "unauthorized"))).toBe(true);
    expect(isSessionExpiredError(new ApiError(401, "invalid token"))).toBe(true);
    expect(isVerificationFailedError(new ApiError(401, "invalid token"))).toBe(false);
  });

  it("other failures classify as neither", () => {
    expect(isVerificationFailedError(new ApiError(500, "boom"))).toBe(false);
    expect(isSessionExpiredError(new ApiError(500, "boom"))).toBe(false);
    expect(isVerificationFailedError(new Error("network"))).toBe(false);
    expect(isSessionExpiredError("not an error object")).toBe(false);
  });
});

tests/vectors.test.ts.source:
/**
 * Cross-platform crypto verification — the REAL modules, not a re-derivation.
 *
 * These tests import the shipping src/crypto code (node engine behind the
 * same interface) and prove byte-for-byte agreement with the backend
 * reference values in shared/vectors.json, including the non-ASCII and
 * astral AAD vectors that pin the ensure_ascii canonicalization contract.
 *
 * DEVICE-ENGINE GAP: everything here runs on the `node:crypto` engine
 * fallback (see src/crypto/engine.ts) — the shipping on-device engine,
 * react-native-quick-crypto, is never exercised by any automated test. Its
 * AES-GCM/PBKDF2/HKDF paths are assumed to match node:crypto byte-for-byte.
 * To pin these vectors on-device in the future, run this same suite inside
 * the RN app (e.g. an in-app dev screen or e2e harness that loads
 * shared/vectors.json and executes the same assertions through the real
 * engine); do not reimplement the vectors in native code.
 */
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { describe, expect, it } from "vitest";

import { deriveMasterKey, deriveAuthKey, deriveDataKey } from "../src/crypto/kdf";
import { buildAad, decrypt, encrypt } from "../src/crypto/envelope";

const here = dirname(fileURLToPath(import.meta.url));
const vectorsPath = join(here, "..", "..", "shared", "vectors.json");
const { vectors, encrypt_vectors: encryptVectors } = JSON.parse(readFileSync(vectorsPath, "utf8"));

describe("shared/vectors.json against the real TS crypto stack", () => {
  it("has vectors to check", () => {
    expect(vectors.length).toBeGreaterThanOrEqual(4);
  });

  for (const [i, v] of vectors.entries()) {
    it(`vector ${i}: KDF + envelope agree with the backend`, () => {
      const salt = Buffer.from(v.salt, "base64");
      const master = deriveMasterKey(v.password, salt, v.iterations);
      expect(master.toString("base64")).toBe(v.master_key);

      const authKey = deriveAuthKey(master);
      expect(authKey.toString("base64")).toBe(v.auth_key);

      const dataKey = deriveDataKey(master);
      expect(dataKey.toString("base64")).toBe(v.data_key);

      const aad = Buffer.from(v.aad, "base64");
      const blob = Buffer.from(v.blob, "base64");
      const plaintext = decrypt(dataKey, blob, aad);
      expect(plaintext.toString("base64")).toBe(v.plaintext);
    });

    it(`vector ${i}: AAD tampering fails closed`, () => {
      const salt = Buffer.from(v.salt, "base64");
      const dataKey = deriveDataKey(deriveMasterKey(v.password, salt, v.iterations));
      const blob = Buffer.from(v.blob, "base64");
      expect(() => decrypt(dataKey, blob, buildAad("entry", "other-user", "x"))).toThrow();
    });
  }
});

describe("fixed-nonce encrypt vectors (mobile -> backend direction)", () => {
  // The decrypt-only vectors above pin Python's output; this family pins what
  // THIS client emits, byte-for-byte, so the backend test can independently
  // decrypt it. AAD is rebuilt from the vector's PARTS — never the stored
  // bytes — which also exercises buildAad against every vector part set.
  it("has encrypt vectors to check, including a no-AAD case", () => {
    expect(encryptVectors.length).toBeGreaterThanOrEqual(2);
    // Pins the families beyond 3-part 'entry': 2-part moodlog/unlockproof
    // AADs, an empty plaintext, and the AAD-less secureStore path.
    expect(encryptVectors.some((v) => v.aad_parts === null)).toBe(true);
    expect(encryptVectors.some((v) => v.plaintext === "")).toBe(true);
    expect(encryptVectors.some((v) => v.aad_parts?.[0] === "moodlog")).toBe(true);
    expect(encryptVectors.some((v) => v.aad_parts?.[0] === "unlockproof")).toBe(true);
  });

  for (const [i, v] of encryptVectors.entries()) {
    it(`encrypt vector ${i}: fixed-nonce encrypt reproduces the blob byte-for-byte`, () => {
      const salt = Buffer.from(v.salt, "base64");
      const dataKey = deriveDataKey(deriveMasterKey(v.password, salt, v.iterations));
      const aad = v.aad_parts ? buildAad(...v.aad_parts) : undefined;
      const nonce = Buffer.from(v.nonce, "base64");
      const blob = encrypt(dataKey, Buffer.from(v.plaintext, "base64"), aad, nonce);
      expect(blob.toString("base64")).toBe(v.blob);
    });

    it(`encrypt vector ${i}: mobile decrypts the pinned blob (backend's encrypt output)`, () => {
      const salt = Buffer.from(v.salt, "base64");
      const dataKey = deriveDataKey(deriveMasterKey(v.password, salt, v.iterations));
      const aad = v.aad_parts ? buildAad(...v.aad_parts) : undefined;
      const plaintext = decrypt(dataKey, Buffer.from(v.blob, "base64"), aad);
      expect(plaintext.toString("base64")).toBe(v.plaintext);
    });
  }

  it("nonce seam: wrong-size nonce fails loudly, omission stays random", () => {
    const key = Buffer.alloc(32, 7);
    expect(() => encrypt(key, Buffer.from("data"), undefined, Buffer.alloc(8))).toThrow();
    const a = encrypt(key, Buffer.from("data"));
    const b = encrypt(key, Buffer.from("data"));
    expect(a.equals(b)).toBe(false);
  });
});

describe("AAD canonicalization (ensure_ascii contract)", () => {
  // Expected bytes pinned from Python:
  // json.dumps([...], separators=(",",":"), ensure_ascii=True)
  it("matches Python for non-ASCII, astral, DEL and control characters", () => {
    const expected = '["\\u00fcn\\u00efcode","\\ud83e\\udde0-brain","del\\u007f","back\\bfeed\\f"]';
    expect(
      buildAad("ünïcode", "🧠-brain", "del\u007f", "back\bfeed\f").toString("utf8"),
    ).toBe(expected);
  });

  it("is collision-free across split positions (no concatenation ambiguity)", () => {
    expect(buildAad("a", "b").toString("utf8")).not.toBe(buildAad("ab", "").toString("utf8"));
    expect(buildAad("1", "23").toString("utf8")).not.toBe(buildAad("12", "3").toString("utf8"));
  });
});

tests/reconnectFlush.test.ts.source:
/**
 * flushQueueOnReconnect: the AppState-driven sync trigger. A foregrounding
 * with a live session and a non-empty queue flushes; throttled so a
 * foreground/background flap cannot stampede the server; failures leave
 * the queue intact for the next trigger.
 *
 * Module state (the throttle timestamp) is per-file here, so this suite
 * gets its own file — store.test.tsx asserts the AppState wiring against
 * the mocked module instead.
 */
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import storage from "./helpers/storageMock";

vi.mock("../src/api/client", () => {
  class ApiError extends Error {
    constructor(public status: number, message: string) {
      super(message);
    }
  }
  return {
    ApiError,
    api: {
      getUserId: vi.fn(async () => "alice"),
      createEntry: vi.fn(async () => ({})),
    },
  };
});

// eslint-disable-next-line @typescript-eslint/no-var-requires
const { api } = await import("../src/api/client") as any;
const { enqueue, queueLength, clearQueue, flushQueueOnReconnect } = await import("../src/offlineQueue");

const entry = (n: number) => ({
  userId: "alice",
  clientEntryId: `r-${n}`,
  blobB64: Buffer.alloc(40, n).toString("base64"),
  entryDate: "2026-09-01",
});

// The throttle timestamp is module state: each test starts the fake clock
// one minute later than the previous one so suites never share a window.
let clock: number | undefined;

beforeEach(() => {
  storage.__reset();
  vi.mocked(api.getUserId).mockClear();
  vi.mocked(api.getUserId).mockImplementation(async () => "alice");
  vi.mocked(api.createEntry).mockClear();
  vi.mocked(api.createEntry).mockImplementation(async () => ({}));
  vi.useFakeTimers();
  clock = (clock ?? Date.parse("2026-09-07T00:00:00Z")) + 60_000;
  vi.setSystemTime(clock);
});

afterEach(() => {
  vi.useRealTimers();
});

describe("flushQueueOnReconnect", () => {
  it("flushes a non-empty queue when a session exists", async () => {
    await enqueue(entry(1));
    await flushQueueOnReconnect();
    expect(api.createEntry).toHaveBeenCalledTimes(1);
    expect(await queueLength()).toBe(0);
  });

  it("does nothing when signed out or when the queue is empty", async () => {
    vi.mocked(api.getUserId).mockResolvedValue(null as never);
    await enqueue(entry(1));
    await flushQueueOnReconnect();
    expect(api.createEntry).not.toHaveBeenCalled();
    expect(await queueLength()).toBe(1); // the entry waits for its owner

    // Empty queue: no upload, and the flush itself is skipped cheaply.
    // (Advance past the throttle window — this test's first call consumed it.)
    vi.advanceTimersByTime(11_000);
    vi.mocked(api.getUserId).mockResolvedValue("alice" as never);
    await clearQueue();
    vi.mocked(api.createEntry).mockClear();
    await flushQueueOnReconnect();
    expect(api.createEntry).not.toHaveBeenCalled();
  });

  it("throttles rapid foreground/background flaps", async () => {
    await enqueue(entry(1));
    vi.mocked(api.createEntry).mockRejectedValue(new Error("offline")); // stays queued
    await flushQueueOnReconnect();
    await flushQueueOnReconnect(); // seconds later: throttled, not a stampede
    await flushQueueOnReconnect();
    expect(api.createEntry).toHaveBeenCalledTimes(1);
  });

  it("flushes again once the throttle window has passed", async () => {
    await enqueue(entry(1));
    vi.mocked(api.createEntry).mockRejectedValue(new Error("offline"));
    await flushQueueOnReconnect();
    expect(api.createEntry).toHaveBeenCalledTimes(1);
    vi.advanceTimersByTime(31_000); // past BOTH the 10s throttle and the item's ≤30s backoff
    await flushQueueOnReconnect();
    expect(api.createEntry).toHaveBeenCalledTimes(2);
  });

  it("a failed flush never throws and keeps the ciphertext queued", async () => {
    await enqueue(entry(1));
    vi.mocked(api.createEntry).mockRejectedValue(new Error("offline"));
    await expect(flushQueueOnReconnect()).resolves.toBeUndefined();
    expect(await queueLength()).toBe(1);
  });
});

tests/moodLog.pins.test.ts.source:
/**
 * Deep-mutation pins for the mood log (2026-09-15 Stryker campaign).
 * Targets (see /tmp/surv_moodLog.ts.txt): the year padStart in localDateISO,
 * the strict ^YYYY-MM-DD$ anchors, the oldest-first sort, the MAX_DAYS=400
 * write cap (boundary: the 401st day drops the oldest), and recentMoods'
 * own -days slice. The localDateISO timezone block lives in moodLog.test.ts
 * and is deliberately not duplicated here.
 */
// @ts-nocheck

import { beforeEach, describe, expect, it } from "vitest";
import storage from "./helpers/storageMock";

const { recordMood, recentMoods, localDateISO } = await import("../src/moodLog");

const keyA = Buffer.alloc(32, 1);

const day = (offset: number): string => {
  const d = new Date(Date.UTC(2026, 8, 4 + offset));
  return d.toISOString().slice(0, 10);
};

beforeEach(() => {
  storage.__reset();
});

describe("moodLog pins: localDateISO year padding", () => {
  it("pads a sub-4-digit year with zeros (year 999 renders as 0999)", () => {
    const d = new Date(2026, 0, 5);
    d.setFullYear(999);
    // padStart(4, "0") is load-bearing: an empty pad string returns "999"
    // un-padded and the date would read "999-01-05".
    expect(localDateISO(d)).toBe("0999-01-05");
  });
});

describe("moodLog pins: strict date anchors in sanitize", () => {
  it("a date with junk before the YYYY-MM-DD body is dropped (leading ^ is strict)", async () => {
    await storage.setItem(
      "mindpattern.moodlog.u1",
      JSON.stringify([
        { date: "x2026-09-01", value: 0.5 },
        { date: "2026-09-02", value: 0.4 },
      ]),
    );
    const days = await recentMoods(keyA, "u1", 30);
    expect(days).toEqual([{ date: "2026-09-02", value: 0.4 }]);
  });

  it("a date with trailing extra digits is dropped (trailing $ is strict)", async () => {
    await storage.setItem(
      "mindpattern.moodlog.u1",
      JSON.stringify([
        { date: "2026-09-012", value: 0.5 },
        { date: "2026-09-03", value: 0.25 },
      ]),
    );
    const days = await recentMoods(keyA, "u1", 30);
    expect(days).toEqual([{ date: "2026-09-03", value: 0.25 }]);
  });
});

describe("moodLog pins: oldest-first ordering", () => {
  it("stored days are re-sorted by date, not kept in payload order", async () => {
    await storage.setItem(
      "mindpattern.moodlog.u1",
      JSON.stringify([
        { date: "2026-09-05", value: -0.5 },
        { date: "2026-09-04", value: 0.3 },
        { date: "2026-09-06", value: 0.9 },
      ]),
    );
    const days = await recentMoods(keyA, "u1", 30);
    expect(days.map((d) => d.date)).toEqual(["2026-09-04", "2026-09-05", "2026-09-06"]);
    expect(days.map((d) => d.value)).toEqual([0.3, -0.5, 0.9]);
  });
});

describe("moodLog pins: MAX_DAYS write cap", () => {
  it("recording the 401st day drops exactly the oldest day (400 survive)", async () => {
    // Days -400..0 = 401 distinct days; slice(-400) must keep -400..-1 EXCLUSIVE
    // of the oldest (-400 is dropped, keeping -399..0).
    for (let offset = -400; offset <= 0; offset += 1) {
      await recordMood(keyA, "u1", day(offset), 0.1);
    }
    const days = await recentMoods(keyA, "u1", 500);
    expect(days).toHaveLength(400);
    expect(days[0].date).toBe(day(-399));
    expect(days[399].date).toBe(day(0));
  });
});

describe("moodLog pins: recentMoods window", () => {
  it("recentMoods(days) returns exactly the newest N days", async () => {
    await recordMood(keyA, "u1", "2026-09-01", -1);
    await recordMood(keyA, "u1", "2026-09-02", 0);
    await recordMood(keyA, "u1", "2026-09-03", 1);
    const two = await recentMoods(keyA, "u1", 2);
    expect(two.map((d) => d.date)).toEqual(["2026-09-02", "2026-09-03"]);
    const four = await recentMoods(keyA, "u1", 4);
    expect(four).toHaveLength(3); // a window larger than the log keeps all
  });
});

tests/crisisDialog.test.ts.source:
/**
 * crisisDialog.ts: the once-per-calendar-day throttle for the crisis
 * support dialog. Pins the per-account ISO date stamp, the day rollover,
 * the account isolation, and — the safety property — that a storage
 * failure can never PERMANENTLY suppress the dialog (fail toward showing).
 */
import { beforeEach, describe, expect, it, vi } from "vitest";

const {
  crisisDialogShownOn,
  recordCrisisDialogShown,
  clearCrisisDialogStamp,
} = await import("../src/crisisDialog");
const storage = (await import("./helpers/storageMock")).default;

const STAMP_KEY = "@mindpattern/crisis_dialog_user-1";

beforeEach(() => {
  storage.__reset();
});

describe("crisisDialog throttle", () => {
  it("is not shown before any record, and the record lands as an ISO date stamp", async () => {
    expect(await crisisDialogShownOn("user-1", "2026-09-14")).toBe(false);
    await recordCrisisDialogShown("user-1", "2026-09-14");
    expect(await storage.getItem(STAMP_KEY)).toBe("2026-09-14");
    expect(await crisisDialogShownOn("user-1", "2026-09-14")).toBe(true);
  });

  it("a new calendar day re-arms the dialog", async () => {
    await recordCrisisDialogShown("user-1", "2026-09-14");
    expect(await crisisDialogShownOn("user-1", "2026-09-15")).toBe(false);
    // …and a re-show restamps the day.
    await recordCrisisDialogShown("user-1", "2026-09-15");
    expect(await storage.getItem(STAMP_KEY)).toBe("2026-09-15");
  });

  it("throttles per account — a second account on the same device is unaffected", async () => {
    await recordCrisisDialogShown("user-1", "2026-09-14");
    expect(await crisisDialogShownOn("user-2", "2026-09-14")).toBe(false);
  });

  it("a failed WRITE still throttles within the session (memory mirror)", async () => {
    const original = storage.setItem;
    storage.setItem = vi.fn(async () => {
      throw new Error("disk gone");
    }) as never;
    try {
      await recordCrisisDialogShown("user-1", "2026-09-14"); // must not throw
    } finally {
      storage.setItem = original;
    }
    // Storage has nothing, yet the mirror suppresses the repeat…
    expect(await storage.getItem(STAMP_KEY)).toBeNull();
    const originalGet = storage.getItem;
    storage.getItem = vi.fn(async () => {
      throw new Error("disk gone");
    }) as never;
    try {
      expect(await crisisDialogShownOn("user-1", "2026-09-14")).toBe(true);
      expect(await crisisDialogShownOn("user-1", "2026-09-15")).toBe(false);
    } finally {
      storage.getItem = originalGet;
    }
  });

  it("a failed READ with no memory record fails toward SHOWING the dialog", async () => {
    // A fresh account id: the module's memory mirror is process state, so
    // this test must not inherit a stamp an earlier test recorded.
    const original = storage.getItem;
    storage.getItem = vi.fn(async () => {
      throw new Error("disk gone");
    }) as never;
    try {
      expect(await crisisDialogShownOn("user-reader", "2026-09-14")).toBe(false);
    } finally {
      storage.getItem = original;
    }
  });

  it("clearCrisisDialogStamp wipes both the stored stamp and the mirror", async () => {
    await recordCrisisDialogShown("user-1", "2026-09-14");
    await clearCrisisDialogStamp("user-1");
    expect(await storage.getItem(STAMP_KEY)).toBeNull();
    // The mirror is wiped too: even with storage broken, the next check
    // fails toward showing (not toward a stale suppression).
    const original = storage.getItem;
    storage.getItem = vi.fn(async () => {
      throw new Error("disk gone");
    }) as never;
    try {
      expect(await crisisDialogShownOn("user-1", "2026-09-14")).toBe(false);
    } finally {
      storage.getItem = original;
    }
  });
});

tests/vault.test.ts.source:
/**
 * Vault lifecycle: memory-only key custody, zeroization on rotation and
 * lock, locked-access failure, and observer notification semantics.
 */
import { beforeEach, describe, expect, it, vi } from "vitest";

import { vault } from "../src/vault";

const keysOf = (fill: number) => ({
  masterKey: Buffer.alloc(32, fill),
  authKey: Buffer.alloc(32, fill + 1),
  dataKey: Buffer.alloc(32, fill + 2),
});

beforeEach(() => {
  vault.lock(); // reset to a known locked state; also drops stale listeners? (it does not — see below)
});

describe("vault", () => {
  it("starts locked: get() throws and isUnlocked() is false", () => {
    expect(vault.isUnlocked()).toBe(false);
    expect(() => vault.get()).toThrow("vault is locked");
  });

  it("unlock stores keys and notifies subscribers; get() returns them", () => {
    const listener = vi.fn();
    const unsubscribe = vault.subscribe(listener);
    const keys = keysOf(1);
    vault.unlock(keys);
    expect(vault.isUnlocked()).toBe(true);
    // L5: get() returns a fresh object each call — callers cannot mutate the
    // vault's own reference — while sharing the underlying buffers so
    // zeroize-on-lock still reaches every copy.
    expect(vault.get()).toStrictEqual({ authKey: keys.authKey, dataKey: keys.dataKey });
    expect(listener).toHaveBeenCalledTimes(1);

    // The master key is zeroized on hand-off: only auth/data remain useful.
    expect(keys.masterKey.equals(Buffer.alloc(32))).toBe(true);
    expect(keys.authKey.equals(Buffer.alloc(32, 2))).toBe(true);

    unsubscribe();
  });

  it("get() never hands out the master key — it is not retained after unlock", () => {
    const keys = keysOf(5);
    vault.unlock(keys);
    const session = vault.get();
    // The zeroized master key must not ride along as dead bytes a future
    // caller could silently use: the field is gone from the session object.
    expect("masterKey" in session).toBe(false);
    expect(session.authKey.equals(Buffer.alloc(32, 6))).toBe(true);
    expect(session.dataKey.equals(Buffer.alloc(32, 7))).toBe(true);
  });

  it("re-unlocking zeroizes the previous session's keys first", () => {
    const first = keysOf(10);
    vault.unlock(first);
    vault.unlock(keysOf(20));
    expect(first.authKey.equals(Buffer.alloc(32))).toBe(true);
    expect(first.dataKey.equals(Buffer.alloc(32))).toBe(true);
    expect(vault.get().authKey.equals(Buffer.alloc(32, 21))).toBe(true);
  });

  it("lock zeroizes the current keys, clears state and notifies", () => {
    const keys = keysOf(30);
    vault.unlock(keys);
    const listener = vi.fn();
    vault.subscribe(listener);
    vault.lock();
    expect(vault.isUnlocked()).toBe(false);
    expect(keys.authKey.equals(Buffer.alloc(32))).toBe(true);
    expect(keys.dataKey.equals(Buffer.alloc(32))).toBe(true);
    expect(listener).toHaveBeenCalledTimes(1);
    expect(() => vault.get()).toThrow("vault is locked");
  });

  it("lock() on an already-locked vault is a safe no-op that still notifies", () => {
    const listener = vi.fn();
    vault.subscribe(listener);
    vault.lock();
    expect(listener).toHaveBeenCalledTimes(1);
  });

  it("unsubscribe stops further notifications", () => {
    const listener = vi.fn();
    const unsubscribe = vault.subscribe(listener);
    vault.unlock(keysOf(40));
    unsubscribe();
    vault.lock();
    expect(listener).toHaveBeenCalledTimes(1);
  });

  it("notifies every subscribed listener", () => {
    const a = vi.fn();
    const b = vi.fn();
    vault.subscribe(a);
    const offB = vault.subscribe(b);
    vault.unlock(keysOf(50));
    offB();
    vault.lock();
    expect(a).toHaveBeenCalledTimes(2);
    expect(b).toHaveBeenCalledTimes(1);
  });
});

