/**
 * Parity + invariant tests for the embedded generic question pool.
 *
 * src/genericQuestions.ts is an EMBEDDED COPY of shared/generic_questions.json
 * (Metro cannot import outside the project root). This suite reads the
 * shared file from disk and pins array parity, the content invariants
 * (questions end with "?", no advice language), and the rotation
 * properties (same question all day, rotates daily, always in-pool).
 */
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";

import { GENERIC_QUESTIONS, genericQuestionForDate } from "../src/genericQuestions";

const here = dirname(fileURLToPath(import.meta.url));
const shared = JSON.parse(readFileSync(join(here, "..", "..", "shared", "generic_questions.json"), "utf8")) as {
  v: number;
  questions: string[];
};

describe("shared/generic_questions.json parity", () => {
  it("embeds the pool exactly", () => {
    expect(shared.v).toBe(1);
    expect([...GENERIC_QUESTIONS]).toEqual(shared.questions);
  });

  it("honors the content invariants: questions only, no advice language", () => {
    for (const question of GENERIC_QUESTIONS) {
      expect(question.endsWith("?")).toBe(true);
      expect(question.toLowerCase()).not.toContain("should");
    }
  });
});

describe("genericQuestionForDate rotation", () => {
  it("is deterministic: the same date always yields the same question", () => {
    expect(genericQuestionForDate("2026-09-07")).toBe(genericQuestionForDate("2026-09-07"));
  });

  it("always returns a pool member", () => {
    for (let day = 1; day <= 30; day++) {
      const date = `2026-09-${String(day).padStart(2, "0")}`;
      expect(GENERIC_QUESTIONS).toContain(genericQuestionForDate(date));
    }
  });

  it("rotates daily over a month (and month boundaries stay stable)", () => {
    const seen = new Set<string>();
    for (let day = 1; day <= 30; day++) {
      seen.add(genericQuestionForDate(`2026-09-${String(day).padStart(2, "0")}`));
    }
    // Not a constant pick; adjacent days step through the pool.
    expect(seen.size).toBeGreaterThanOrEqual(4);
    // Month boundaries are just dates: deterministic and in-pool.
    expect(GENERIC_QUESTIONS).toContain(genericQuestionForDate("2026-09-30"));
    expect(GENERIC_QUESTIONS).toContain(genericQuestionForDate("2026-10-01"));
    // The default form (today) returns a pool member.
    expect(GENERIC_QUESTIONS).toContain(genericQuestionForDate());
  });
});

tests/engine.test.ts.source:
/**
 * engine.ts loader branches, imported lazily inside each test so that a
 * mutant breaking module initialization fails the TEST (a collection-level
 * failure is invisible to mutation runners' kill accounting).
 */
import { describe, expect, it } from "vitest";
import nodeCrypto from "node:crypto";

describe("crypto engine loader", () => {
  it("module-level engine resolves a working backend via require()", async () => {
    const { engine } = await import("../src/crypto/engine");
    // vite-node's require + the quickCryptoMock alias -> node:crypto.
    expect(engine.randomBytes(4)).toHaveLength(4);
    expect(engine.pbkdf2Sync("pw", Buffer.alloc(8), 1, 32, "sha256")).toHaveLength(32);
  });

  it("prefers react-native-quick-crypto when the resolver provides it", async () => {
    const { loadEngine } = await import("../src/crypto/engine");
    const sentinel = { randomBytes: () => Buffer.alloc(0) } as never;
    const req = (id: string) => (id === "react-native-quick-crypto" ? sentinel : nodeCrypto);
    expect(loadEngine(req)).toBe(sentinel);
  });

  it("falls back to node:crypto when quick-crypto cannot load", async () => {
    const { loadEngine } = await import("../src/crypto/engine");
    const req = (id: string) => {
      if (id === "react-native-quick-crypto") throw new Error("native addon unavailable");
      if (id === "node:crypto") return nodeCrypto;
      throw new Error(`unexpected require: ${id}`);
    };
    const resolved = loadEngine(req);
    expect(Buffer.from(resolved.hkdfSync("sha256", Buffer.alloc(32, 1), Buffer.alloc(32), Buffer.alloc(0), 32) as ArrayBuffer)).toHaveLength(32);

    const cipher = resolved.createCipheriv("aes-256-gcm", Buffer.alloc(32, 2), Buffer.alloc(12, 3));
    cipher.setAAD(Buffer.from("aad"));
    const ct = Buffer.concat([cipher.update(Buffer.from("m")), cipher.final()]);
    expect(ct.length).toBe(1);
    expect(cipher.getAuthTag()).toHaveLength(16);
  });

  it("fails loudly when no require() exists at all", async () => {
    const { loadEngine } = await import("../src/crypto/engine");
    // In an ESM-only host the bare `require` reference throws
    // ReferenceError at module load — loud on purpose.
    const req = () => {
      throw new ReferenceError("require is not defined");
    };
    expect(() => loadEngine(req)).toThrow(ReferenceError);
  });
});

